use serde::Serialize; use crate::ir::{Instruction, IrModule, Operand};
#[derive(Debug, Clone, Serialize)] pub struct MachineProgram { pub target: String, pub instructions: Vec<String> }
pub fn emit(module: &IrModule) -> MachineProgram { let mut instructions = Vec::new(); for function in &module.functions { instructions.push(format!(".globl {}", function.name)); instructions.push(format!("{}:", function.name)); for instruction in &function.instructions { match instruction { Instruction::Constant { destination, value } => instructions.push(format!("  mov {destination}, #{value}")), Instruction::Binary { destination, operator, left, right } => instructions.push(format!("  {operator} {destination}, {}, {}", operand(left), operand(right))), Instruction::Store { name, value } => instructions.push(format!("  store {}, @{name}", operand(value))), Instruction::Return { value } => instructions.push(format!("  ret {}", operand(value))) } } } MachineProgram { target: "Craft-32".into(), instructions } }
fn operand(value: &Operand) -> String { match value { Operand::Constant(value) => format!("#{value}"), Operand::Temporary(value) => value.clone() } }
